// Generar respuesta de cotización
const inputData = $input.first().json;
const mensaje = inputData.mensaje || '';
const telefono = inputData.telefono || '';
const nombre = inputData.nombre || '';

// Lista de precios de referencia
const precios = {
  'cambio de aceite': '🔧 *Cambio de Aceite*: $250 - $450 (según tipo de aceite)',
  'aceite': '🔧 *Cambio de Aceite*: $250 - $450 (según tipo de aceite)',
  'frenos': '🔧 *Revisión y Cambio de Frenos*: \n- Balatas: $350 - $600\n- Liquido de frenos: $150\n- Rectificación de disco: $400',
  'llanta': '🔧 *Llanta*: $800 - $2,500 (según marca y medida)',
  'llantas': '🔧 *Llanta*: $800 - $2,500 (según marca y medida)',
  'cadena': '🔧 *Cadena de Transmisión*: \n- Cadena: $450 - $900\n- Kit de arrastre (catalina + piñon): $600 - $1,200',
  'bateria': '🔧 *Batería*: $600 - $1,500 (según modelo)',
  'batería': '🔧 *Batería*: $600 - $1,500 (según modelo)',
  'afinacion': '🔧 *Afinación*: $800 - $1,500 (incluye bujías, filtros y carburación)',
  'afinación': '🔧 *Afinación*: $800 - $1,500 (incluye bujías, filtros y carburación)',
  'suspension': '🔧 *Suspensión*: \n- Horquilla delantera: $500 - $1,000\n- Amortiguadores traseros: $800 - $2,000',
  'suspensión': '🔧 *Suspensión*: \n- Horquilla delantera: $500 - $1,000\n- Amortiguadores traseros: $800 - $2,000',
  'revision': '🔧 *Revisión General*: $300 (aplica con cualquier servicio)',
  'revisión': '🔧 *Revisión General*: $300 (aplica con cualquier servicio)',
  'escapes': '🔧 *Sistema de Escape*: \n- Reparación: $400 - $800\n- Cambio de silenciador: $600 - $2,000',
  'escape': '🔧 *Sistema de Escape*: \n- Reparación: $400 - $800\n- Cambio de silenciador: $600 - $2,000',
  'luces': '🔧 *Sistema Eléctrico* (luces, direccionales): $200 - $600',
  'electrico': '🔧 *Sistema Eléctrico*: $300 - $1,000 (según diagnóstico)',
  'eléctrico': '🔧 *Sistema Eléctrico*: $300 - $1,000 (según diagnóstico)',
  'carburacion': '🔧 *Carburación / Inyección*: \n- Limpieza de carburador: $400\n- Sincronización: $300\n- Calibración de inyectores: $600',
  'carburación': '🔧 *Carburación / Inyección*: \n- Limpieza de carburador: $400\n- Sincronización: $300\n- Calibración de inyectores: $600'
};

// Buscar servicio solicitado en el mensaje
const mensajeLower = mensaje.toLowerCase();
let respuesta = '';
let serviciosEncontrados = [];

for (const [keyword, precio] of Object.entries(precios)) {
  if (mensajeLower.includes(keyword)) {
    serviciosEncontrados.push(precio);
  }
}

if (serviciosEncontrados.length > 0) {
  respuesta = 'Hola ' + (nombre || '') + ', gracias por contactarnos. 😊\n\n'
    + 'Aquí tienes nuestros precios de referencia:\n\n'
    + serviciosEncontrados.join('\n\n')
    + '\n\n⚠️ *Nota*: Los precios pueden variar según el modelo y año de tu moto.\n'
    + 'Te recomendamos pasar al taller para una cotización precisa y sin costo.\n\n'
    + '📍 Calle Principal #123, Col. Centro\n'
    + '📞 Tel: 123-456-7890';
} else {
  respuesta = 'Hola ' + (nombre || '') + ', gracias por contactarnos. 😊\n\n'
    + 'Con gusto te proporcionamos nuestros *precios de referencia*:\n\n'
    + '🔧 *Cambio de Aceite*: $250 - $450\n'
    + '🔧 *Afinación General*: $800 - $1,500\n'
    + '🔧 *Frenos (balatas + rectificación)*: $350 - $1,000\n'
    + '🔧 *Llanta*: $800 - $2,500\n'
    + '🔧 *Cadena y Arrastre*: $450 - $1,200\n'
    + '🔧 *Batería*: $600 - $1,500\n'
    + '🔧 *Revisión General*: $300\n\n'
    + '¿Podrías indicarnos qué servicio en particular te interesa?\n'
    + 'Con gusto te damos un precio más exacto. 😊\n\n'
    + '📍 Calle Principal #123, Col. Centro';
}

return [
  {
    json: {
      telefono: telefono,
      mensaje: mensaje,
      respuesta: respuesta,
      categoria: 'COTIZACION'
    }
  }
];
